import { ALLAH_NAMES } from "./names";
import { EXTRA_QUOTES } from "./quote-extra";

export type Dhikr = {
  id: string;
  arabic: string;
  name: string;
  short: string;
  meaning: string;
  primary: boolean;
  /** Только во вкладке «Азкары», не в ленте поминаний. */
  azkar?: boolean;
  reward: string;
  source: string;
  full?: string;
  /** Русский перевод, если он длиннее короткого смысла. */
  translation?: string;
};

export const REWARD_STEP = 10;

export function rewardPoints(taps: number): number {
  if (!Number.isFinite(taps) || taps <= 0) return 0;
  return Math.floor(taps) * REWARD_STEP;
}

