/** Поминания в ленте и в списке «Поминание». Азкары туда не входят. */
export const REMEMBRANCE = DHIKR.filter((item) => !item.azkar);

export function dhikrById(id: string): Dhikr {
  const found = DHIKR.find((d) => d.id === id);
  if (found) return found;
  const name = ALLAH_NAMES.find((n) => n.id === id);
  if (name) {
    return {
      id: name.id,
      arabic: name.arabic,
      name: name.name,
      short: name.name,
      meaning: name.meaning,
      primary: false,
      reward: name.note,
      source: "Коран",
    };
  }
  return DHIKR[0]!;
}

